\caption{Dependence of effective distortion energy density on $\gammacon$ for the axion and dark photon conversion cases. A sign flip is expected for the axion conversion distortion at $\gammacon \approx 0.13$ which is due to limitations of the approximation (see text for discussion).}
\label{fig:Drho_rho_distortion}
\end{figure}
